{"argv": ["python3", "- <<'PY'
import json,statistics,collections,math
T=json.load(open('train.json'));D=json.load(open('dev_requests.json'))
for task,reqs in D.items():
 print(task,len(reqs),collections.Counter(len(r['history']) for r in reqs))
 # groups based demographics
 groups=collections.defaultdict(list)
 for r in reqs: groups[(r['history'][0]['age'],r['history'][0]['mass'],r['history'][0]['height'])].append(r)
 for g,rs in groups.items():
  lens=[len(r['history']) for r in rs]; last=rs[-1]['history'][-1]
  print(' group',g,'n',len(rs),'lens',min(lens),max(lens),'last',last)
print('\nTRAIN')
for p,rows in T.items():
 w=[r['watts'] for r in rows]; dec=[i for i in range(1,len(w)) if w[i]<w[i-1]]
 print(p,len(rows),'time',rows[0]['time_min'],rows[-1]['time_min'],'demo',rows[0]['age'],rows[0]['mass'],rows[0]['height'],'watts',sorted(set(w)), 'dec',[(rows[i]['time_min'],w[i-1],w[i]) for i in dec], 'core range',min(r['core_temp'] for r in rows),max(r['core_temp'] for r in rows),'missing', {k:sum(r[k] is None for r in rows) for k in ['hr','skin_temp','watts','ambient_temp','humidity']})
